window.addEventListener('DOMContentLoaded',event=>{const sidebarToggle=document.body.querySelector('#sidebarToggle');if(sidebarToggle){sidebarToggle.addEventListener('click',event=>{event.preventDefault();document.body.classList.toggle('sb-sidenav-toggled');localStorage.setItem('sb|sidebar-toggle',document.body.classList.contains('sb-sidenav-toggled'))})}
const sidenavMenu=document.querySelector('.sb-sidenav-menu');const activeLink=sidenavMenu?sidenavMenu.querySelector('.nav-link.active'):null;if(sidenavMenu&&activeLink){const centerActiveLink=()=>{const menuRect=sidenavMenu.getBoundingClientRect();const linkRect=activeLink.getBoundingClientRect();const target=sidenavMenu.scrollTop+(linkRect.top-menuRect.top)-(menuRect.height/2)+(linkRect.height/2);sidenavMenu.scrollTo({top:Math.max(0,target),behavior:'auto'})};requestAnimationFrame(()=>requestAnimationFrame(centerActiveLink));window.addEventListener('load',centerActiveLink)}})